def find_topmost_carpet(n, carpets, point) -> int:
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    try:
        # Basic validation
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non-negative integer")
        if not isinstance(carpets, list) or len(carpets) != n:
            raise ValueError("carpets must be a list of length n")
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError("point must be a tuple of two integers")
        x, y = point
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError("point coordinates must be integers")

        top_index = -1
        for idx, carpet in enumerate(carpets, start=1):
            if not (isinstance(carpet, tuple) and len(carpet) == 4):
                continue  # skip malformed carpet entries
            a, b, g, k = carpet
            if not all(isinstance(v, int) for v in (a, b, g, k)):
                continue  # skip if any component is not an integer
            if g < 0 or k < 0:
                continue  # invalid dimensions, skip
            if a <= x <= a + g and b <= y <= b + k:
                top_index = idx  # keep updating to the latest covering carpet

        return top_index
    except Exception:
        # In case of any unexpected error, return -1 as per specification
        return -1

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build grid with 1-based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # DP over steps t = i1 + j1 = i2 + j2
    # dp[i1][i2] = max sum for current t
    NEG_INF = -10**18
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # start cell counted once

    for t in range(3, 2 * N + 1):  # t ranges from 3 to 2N (since t=2 handled by start)
        new_dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # previous positions: (i1-1,i2-1), (i1-1,i2), (i1,i2-1), (i1,i2)
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1 or pi1 > N:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1 or pi2 > N:
                            continue
                        if dp[pi1][pi2] > best:
                            best = dp[pi1][pi2]
                if best == NEG_INF:
                    continue
                if i1 == i2 and j1 == j2:
                    val = grid[i1][j1]
                else:
                    val = grid[i1][j1] + grid[i2][j2]
                new_dp[i1][i2] = best + val
        dp = new_dp

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the number string.
    """
    # Validate inputs
    if not isinstance(num_str, str) or not num_str.isdigit():
        raise ValueError("num_str must be a string of digits")
    if N != len(num_str):
        raise ValueError("N must equal the length of num_str")
    if K < 0 or K > N - 1:
        raise ValueError("K must be between 0 and N-1 inclusive")

    # Special case: no multiplication signs
    if K == 0:
        return int(num_str)

    # Precompute integer values of all substrings
    int_sub = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            int_sub[i][j] = val

    # DP table: dp[i][k] = max product for prefix of length i with k multiplications
    dp = [[None] * (K + 1) for _ in range(N + 1)]

    # Base case: k = 0
    for i in range(1, N + 1):
        dp[i][0] = int_sub[0][i]

    # Fill DP
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):  # need at least k+1 digits
            max_prod = None
            # split point j: last number starts at j
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                prod = prev * int_sub[j][i]
                if max_prod is None or prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    result = dp[N][K]
    return result if result is not None else 0

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If inputs are logically inconsistent (e.g., wrong length of coeffs or negative degree).
    """
    # Basic input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1} for degree {n}")
    for idx, c in enumerate(coeffs):
        if not isinstance(c, int):
            raise TypeError(f"Coefficient at index {idx} is not an integer")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    from collections import deque
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        return "NO ANSWER!"
    # Quick check
    if A == B:
        return 0
    max_depth = 10
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= max_depth:
            continue
        for src, tgt in rules:
            if not isinstance(src, str) or not isinstance(tgt, str) or src == "":
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.

    Raises:
    - TypeError: If inputs are of incorrect type.
    - ValueError: If n is negative.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for r in rules:
        if not (isinstance(r, tuple) and len(r) == 2 and
                all(isinstance(x, int) for x in r)):
            raise TypeError("each rule must be a tuple of two integers")

    # Build a mapping from each digit to the list of possible replacements
    rule_map = {}
    for x, y in rules:
        if 0 <= x <= 9 and 0 <= y <= 9:
            rule_map.setdefault(x, []).append(y)

    from collections import deque

    start_str = str(n)
    visited = {start_str}
    queue = deque([start_str])

    while queue:
        current = queue.popleft()
        digits = list(current)
        for idx, ch in enumerate(digits):
            d = int(ch)
            if d in rule_map:
                for replacement in rule_map[d]:
                    new_digits = digits.copy()
                    new_digits[idx] = str(replacement)
                    new_str = ''.join(new_digits)
                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append(new_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    try:
        # Basic type validation
        if not isinstance(scenario, str):
            return False
        if not isinstance(liar_count, set) or not all(isinstance(x, str) for x in liar_count):
            return False
        if not isinstance(statements, dict) or not all(isinstance(k, str) and isinstance(v, list) for k, v in statements.items()):
            return False
        if not isinstance(days_of_week, set) or not all(isinstance(x, str) for x in days_of_week):
            return False

        # Helper to determine truth value of a statement
        def evaluate(statement: str, speaker: str) -> bool:
            # Remove trailing period and surrounding whitespace
            stmt = statement.strip().rstrip('.')
            # Check for "I am guilty" or "I am not guilty"
            if stmt == "I am guilty":
                return scenario == speaker
            if stmt == "I am not guilty":
                return scenario != speaker
            # Check for "NAME is guilty" or "NAME is not guilty"
            if " is " in stmt:
                parts = stmt.split(" is ", 1)
                if len(parts) != 2:
                    return True  # treat malformed as true to avoid false negatives
                name, rest = parts[0], parts[1]
                if rest == "guilty":
                    return scenario == name
                if rest == "not guilty":
                    return scenario != name
            # If statement doesn't match known patterns, treat as true (no constraint)
            return True

        for speaker, stmts in statements.items():
            for stmt in stmts:
                # Skip statements that mention any day of the week
                if any(day in stmt for day in days_of_week):
                    continue
                truth = evaluate(stmt, speaker)
                is_liar = speaker
